document.addEventListener('change',e=>{if(e.target.matches('[data-dr-preview-path]')){DR.paths[dwWorkspace().id]=e.target.value;drStore();}if(e.target.matches('[data-dr-script]')){DR.scripts[dwWorkspace().id]=e.target.value;drStore();}if(e.target.matches('[data-dr-checkpoint-choice]')){DR.checkpoint[dwWorkspace().id]=e.target.value;drStore();}});
setInterval(()=>{if(DR.busy||dwPanel.hidden||DW.tab!=='runtime'||!dwWorkspace()||dwWorkspace().kind==='practice')return;const id=dwWorkspace().id;DR.busy=true;void dwApi('runtimeStatus',{workspaceId:id}).then(s=>{if(dwWorkspace()?.id!==id)return;DR.status=s;const box=dwPanel.querySelector('[data-dr-current]'),t=s.tasks.find(t=>t.id===box?.dataset.drCurrent);if(!t)return;box.querySelector('[data-dr-state]').textContent=t.message+(Number.isInteger(t.exitCode)?' · 退出码 '+t.exitCode:'');const log=box.querySelector('[data-dr-log]');if(log.textContent!==t.output){const end=log.scrollTop+log.clientHeight>=log.scrollHeight-30;log.textContent=t.output;if(end)log.scrollTop=log.scrollHeight;}box.querySelector('[data-dr-pause]').disabled=t.settled;box.querySelector('[data-dr-resume]').disabled=!t.settled||!['stopped','failed','interrupted'].includes(t.status);}).catch(()=>{}).finally(()=>{DR.busy=false;});},1000);
